<script setup>
import { state } from '../state'
import Badge from './Badge.vue'
import { rankZone } from '../football'
defineProps({ rows: Array, compact: Boolean, provisional: Boolean, archive: Boolean })
</script>
<template>
  <div class="table-scroll" :class="{ compact }" :tabindex="compact ? undefined : 0" :aria-label="compact ? undefined : 'Classement, tableau à défilement horizontal'"><table class="standings-table"><caption class="sr-only">Classement de Ligue 1{{ provisional ? ' — projection provisoire' : '' }}{{ !archive && state.mode === 'demo' ? ' — données fictives' : '' }}</caption><thead><tr><th scope="col">#</th><th scope="col">Équipe</th><template v-if="!compact"><th scope="col"><abbr title="Matchs joués">MJ</abbr></th><th scope="col"><abbr title="Victoires">V</abbr></th><th scope="col"><abbr title="Matchs nuls">N</abbr></th><th scope="col"><abbr title="Défaites">D</abbr></th><th scope="col"><abbr title="Buts marqués">BP</abbr></th><th scope="col"><abbr title="Buts encaissés">BC</abbr></th></template><th scope="col"><abbr title="Différence de buts">Diff.</abbr></th><th scope="col">Pts</th><th v-if="!compact" scope="col">Forme</th></tr></thead><tbody><tr v-for="row in rows" :key="row.team.id" :class="[{ 'favorite-row': !archive && state.favorite === row.team.id, 'row-in-progress': row.liveMatchId }, compact || archive ? '' : `zone-${rankZone(row.rank, rows.length)}`]"><td class="rank"><span>{{ row.rank }}</span><span v-if="provisional && row.previousRank !== row.rank" class="rank-change" :class="{ down: row.rank > row.previousRank }" :title="`${Math.abs(row.previousRank - row.rank)} place(s) ${row.rank < row.previousRank ? 'gagnée(s)' : 'perdue(s)'}`">{{ row.rank < row.previousRank ? '↗' : '↘' }}</span></td><td><component :is="archive ? 'span' : 'RouterLink'" :to="archive ? undefined : `/equipes/${row.team.id}`" class="table-team"><Badge :team="row.team" size="small" /><span>{{ compact ? row.team.code : row.team.name }}</span><span v-if="row.liveMatchId" class="live-dot table-live-dot" role="img" aria-label="Match en cours" title="Match en cours"></span><span v-if="!archive && state.favorite === row.team.id" class="table-heart" aria-label="Équipe favorite">♥</span></component></td><template v-if="!compact"><td>{{ row.played }}</td><td>{{ row.wins }}</td><td>{{ row.draws }}</td><td>{{ row.losses }}</td><td>{{ row.goalsFor }}</td><td>{{ row.goalsAgainst }}</td></template><td class="muted">{{ row.difference > 0 ? '+' : '' }}{{ row.difference }}</td><td class="points">{{ row.points }}</td><td v-if="!compact"><span class="form"><span v-for="(result, i) in row.form.slice(-5)" :key="i" :class="result" :title="({ W: 'Victoire', D: 'Nul', L: 'Défaite' })[result]">{{ ({ W: 'V', D: 'N', L: 'D' })[result] }}</span><span v-if="!row.form">—</span></span></td></tr></tbody></table></div>
